package org.slavicmyths.nethersmithing.client;
import java.util.*;import com.google.gson.*;import net.minecraft.client.model.*;import net.minecraft.client.model.geom.*;import net.minecraft.client.model.geom.builders.*;import net.minecraft.client.player.AbstractClientPlayer;import net.minecraft.client.resources.PlayerSkin;import net.minecraft.world.entity.*;import net.minecraft.world.item.*;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.client.extensions.common.*;
import org.slavicmyths.nethersmithing.*;
/** Actual separate pieces on vanilla humanoid bones, no server references to this class. */
@EventBusSubscriber(modid="slavicmyths",value=Dist.CLIENT,bus=EventBusSubscriber.Bus.MOD)
public final class NetherArmorClient {
 private static final Map<String,Model> MODELS=new HashMap<>();
 @SubscribeEvent public static void register(RegisterClientExtensionsEvent event){for(var entry:NetherArmor.ITEMS.entrySet())event.registerItem(new IClientItemExtensions(){@Override public HumanoidModel<?> getHumanoidArmorModel(LivingEntity entity,ItemStack stack,EquipmentSlot slot,HumanoidModel<?> original){if(!(stack.getItem() instanceof NetherArmor.Piece p)||!p.king)return original;var model=model(slot,slim(entity));model.animate(entity);return model;}},entry.getValue().get());}
 public static boolean slim(LivingEntity e){return e instanceof AbstractClientPlayer p&&p.getSkin().model()==PlayerSkin.Model.SLIM;}
 public static Model model(EquipmentSlot slot,boolean slim){return MODELS.computeIfAbsent(slot.getName()+slim,key->create(slot,slim));}
 public static Model create(EquipmentSlot slot,boolean slim){try(var in=NetherArmorClient.class.getResourceAsStream("/assets/slavicmyths/nether_armor_rigs/infernal_king.json")){var data=JsonParser.parseReader(new java.io.InputStreamReader(java.util.Objects.requireNonNull(in),java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();var mesh=new MeshDefinition();var root=mesh.getRoot();Map<String,PartDefinition> defs=new LinkedHashMap<>();defs.put("root",root);
  for(String name:List.of("head","hat","body","left_arm","right_arm","left_leg","right_leg")){float x=name.equals("left_arm")?5:name.equals("right_arm")?-5:name.equals("left_leg")?1.9F:name.equals("right_leg")?-1.9F:0;float y=name.contains("arm")?2:name.contains("leg")?12:0;defs.put(name,root.addOrReplaceChild(name,CubeListBuilder.create(),PartPose.offset(x,y,0)));}
  for(var raw:data.getAsJsonArray("parts")){var p=raw.getAsJsonObject();if(!p.get("slot").getAsString().equals(slot.getName()))continue;var size=p.getAsJsonArray("size");var pivot=p.getAsJsonArray("pivot");var off=p.getAsJsonArray("offset");var rot=p.getAsJsonArray("rotation");var uv=p.getAsJsonArray("uv");String name=p.get("name").getAsString(),parent=p.get("parent").getAsString();float side=parent.equals("left_arm")?-.5F:parent.equals("right_arm")?.5F:0;
   var part=defs.get(parent).addOrReplaceChild(name,CubeListBuilder.create().texOffs(uv.get(0).getAsInt(),uv.get(1).getAsInt()).addBox(off.get(0).getAsFloat(),off.get(1).getAsFloat(),off.get(2).getAsFloat(),size.get(0).getAsFloat(),size.get(1).getAsFloat(),size.get(2).getAsFloat()),PartPose.offsetAndRotation(pivot.get(0).getAsFloat()+(slim?side:0),pivot.get(1).getAsFloat(),pivot.get(2).getAsFloat(),rot.get(0).getAsFloat(),rot.get(1).getAsFloat(),rot.get(2).getAsFloat()));defs.put(name,part);
  }return new Model(LayerDefinition.create(mesh,data.get("atlas").getAsInt(),data.get("atlas").getAsInt()).bakeRoot(),slot);
 }catch(java.io.IOException e){throw new IllegalStateException("Missing royal armor source",e);}}
 public static final class Model extends HumanoidModel<LivingEntity>{public final ModelPart root;public final EquipmentSlot slot;private final Map<String,ModelPart> parts=new HashMap<>();
  Model(ModelPart root,EquipmentSlot slot){super(root);this.root=root;this.slot=slot;indexKnown(root);}
  private void indexKnown(ModelPart root){try(var in=NetherArmorClient.class.getResourceAsStream("/assets/slavicmyths/nether_armor_rigs/infernal_king.json")){var data=JsonParser.parseReader(new java.io.InputStreamReader(in,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonObject();for(String name:List.of("head","hat","body","left_arm","right_arm","left_leg","right_leg"))parts.put(name,root.getChild(name));for(var raw:data.getAsJsonArray("parts")){var p=raw.getAsJsonObject();if(p.get("slot").getAsString().equals(slot.getName()))parts.put(p.get("name").getAsString(),parts.get(p.get("parent").getAsString()).getChild(p.get("name").getAsString()));}}catch(java.io.IOException e){throw new IllegalStateException(e);}}
  public void animate(LivingEntity e){float walk=(float)Math.min(1,e.getDeltaMovement().horizontalDistance()*5);pose(e.tickCount,walk,e.isCrouching(),e.isFallFlying());}
  public void pose(float age,float walk,boolean crouch,boolean fly){for(var p:parts.values())p.resetPose();for(int i=0;i<3;i++){var p=parts.get("cape_segment_"+i);if(p!=null){p.xRot=-(.08F+walk*.25F+(float)Math.sin(age*.07-i*.5)*(.02F+walk*.02F))-(crouch?.15F:0)-(fly?.55F:0);}}var tabard=parts.get("tabard_root");if(tabard!=null)tabard.xRot=.05F+walk*.2F+(crouch?.3F:0);}
  public void visibleSlot(){setAllVisible(false);switch(slot){case HEAD->head.visible=true;case CHEST->{body.visible=true;leftArm.visible=true;rightArm.visible=true;}case LEGS->{body.visible=true;leftLeg.visible=true;rightLeg.visible=true;}case FEET->{leftLeg.visible=true;rightLeg.visible=true;}default->{}}}
 }
 private NetherArmorClient(){}
}
